mapper.select:
SELECT cargo_list_id
FROM mes_building_cargo_list_product_link l
INNER JOIN tech_artifact a ON a.id = l.product_id AND l.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ARTIFACT.getType()}
AND a.bool_all_part_send_directly = 0


        AND a.project_id = #{projectId}


        AND a.monomer_id = #{monomerId}




                AND (a.name = #{blurry} OR a.serial_number = #{blurry})


                AND (a.name LIKE CONCAT('%',#{blurry},'%') OR a.serial_number LIKE CONCAT('%',#{blurry},'%'))




union
SELECT cargo_list_id
FROM mes_building_cargo_list_product_link l
INNER JOIN tech_enclosure a ON a.id = l.product_id AND l.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ENCLOSURE.getType()}


        AND a.project_id = #{projectId}


        AND a.monomer_id = #{monomerId}




                AND (a.name = #{blurry} OR a.serial_number = #{blurry})


                AND (a.name LIKE CONCAT('%',#{blurry},'%') OR a.serial_number LIKE CONCAT('%',#{blurry},'%'))




union
SELECT cargo_list_id
FROM mes_building_cargo_list_product_link l
INNER JOIN tech_machine_part a ON a.id = l.product_id AND l.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@MACHINE_PART.getType()}
and a.bool_send_directly = 1


        AND a.project_id = #{projectId}


        AND a.monomer_id = #{monomerId}




                AND (a.name = #{blurry} OR a.serial_number = #{blurry})


                AND (a.name LIKE CONCAT('%',#{blurry},'%') OR a.serial_number LIKE CONCAT('%',#{blurry},'%'))




union
SELECT cargo_list_id
FROM mes_building_cargo_list_product_link l
INNER JOIN tech_assemble a ON a.id = l.product_id AND l.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@ASSEMBLE.getType()}
and a.bool_send_directly = 1


        AND a.project_id = #{projectId}


        AND a.monomer_id = #{monomerId}


union
SELECT cargo_list_id
FROM mes_building_cargo_list_product_link l
INNER JOIN tech_standard_part a ON a.id = l.product_id AND l.product_type = ${@com.hzchum.scim.mes.building.core.api.enums.ProductTypeEnum@AUXILIARY_MATERIAL.getType()}


        AND a.project_id = #{projectId}


        AND a.monomer_id = #{monomerId}




                AND (a.name = #{blurry})


                AND (a.name LIKE CONCAT('%',#{blurry},'%'))

select ifnull(sum(r.quantity), 0)
from mes_building_cargo_list_product_link r
         inner join mes_building_cargo_list cl
                    on cl.id = r.cargo_list_id and cl.bool_delete_enum = 0 and cl.status > 2
                    AND cl.shipment_status != ${@com.hzchum.scim.mes.building.core.api.enums.cargoList.ShipmentStatusEnum@ABOLISH_DELIVERY.getType()}
where r.bool_delete_enum = 0
  and r.product_id = #{productId}
  and r.product_type = #{productType}

select temp.* from (SELECT list.project_id, (case link.product_type when 1 then mp.monomer_id when 2 then a.monomer_id when 8 then sp.monomer_id when 16 then ass.monomer_id else null end) monomer_id, (case link.product_type when 1 then mp.area_id when 2 then a.area_id when 8 then sp.area_id when 16 then ass.area_id else e.enclosure_plan_id end) area_id, list.audit_time, ( CASE link.product_type when 1 then mp.name WHEN 2 THEN a.name when 4 then e.name when 16 then ass.name ELSE sp.name END ) name, ( CASE link.product_type when 1 then mp.serial_number WHEN 2 THEN a.serial_number when 4 then e.serial_number when 16 then ass.serial_number ELSE null END ) serial_number, ( CASE link.product_type when 1 then mp.specification WHEN 2 THEN a.specification when 8 then sp.specification when 16 then ass.specification ELSE null END ) specification, ( CASE link.product_type when 1 then mp.material WHEN 2 THEN a.material when 4 then e.material when 16 then ass.material ELSE null END ) material, link.weight AS mete, link.* FROM mes_building_cargo_list list INNER JOIN mes_building_cargo_list_product_link AS link ON list.id = link.cargo_list_id AND link.warehouse_type in(0,2) LEFT JOIN tech_artifact a ON link.product_type = 2 AND link.product_id = a.id AND a.bool_delete_enum = 0 LEFT JOIN tech_enclosure e ON link.product_type = 4 AND link.product_id = e.id AND e.bool_delete_enum = 0 LEFT JOIN tech_standard_part sp ON link.product_type = 8 AND link.product_id = sp.id AND sp.bool_delete_enum = 0 LEFT JOIN tech_machine_part mp ON link.product_type = 1 AND link.product_id = mp.id AND mp.bool_delete_enum = 0 LEFT JOIN tech_assemble ass ON link.product_type = 16 AND link.product_id = ass.id AND ass.bool_delete_enum = 0 WHERE list.bool_delete_enum = 0 AND link.bool_delete_enum = 0 AND list.`status` IN ( 4, 8 ) AND list.delivery_status = 1 AND (link.product_type IN ( 4, 8 ) or (link.product_type = 1 and mp.bool_all_part_send_directly = 1) or (link.product_type = 2 and a.bool_all_part_send_directly = 0) or (link.product_type = 16 and ass.bool_all_part_send_directly = 1))
AND list.project_id IN
#{projectId}
AND link.product_type = #{productType}
and date(list.audit_time) >= date(#{auditStartDate})
and date(list.audit_time) <= date(#{auditEndDate})
) temp
AND temp.monomer_id = #{monomerId}
AND temp.name like concat('%',#{name},'%')
AND temp.serial_number like concat('%',#{serialNumber},'%')
order by temp.audit_time desc, temp.id desc

select temp.* from (SELECT list.project_id, (case link.product_type when 1 then mp.monomer_id when 2 then a.monomer_id when 8 then sp.monomer_id when 16 then ass.monomer_id else null end) monomer_id, (case link.product_type when 1 then mp.area_id when 2 then a.area_id when 8 then sp.area_id when 16 then ass.area_id else e.enclosure_plan_id end) area_id, list.audit_time, ( CASE link.product_type when 1 then mp.name WHEN 2 THEN a.name when 4 then e.name when 16 then ass.name ELSE sp.name END ) name, ( CASE link.product_type when 1 then mp.serial_number WHEN 2 THEN a.serial_number when 4 then e.serial_number when 16 then ass.serial_number ELSE null END ) serial_number, ( CASE link.product_type when 1 then mp.specification WHEN 2 THEN a.specification when 8 then sp.specification when 16 then ass.specification ELSE null END ) specification, ( CASE link.product_type when 1 then mp.material WHEN 2 THEN a.material when 4 then e.material when 16 then ass.material ELSE null END ) material, ( CASE link.product_type when 1 then mp.remark WHEN 2 THEN a.remark when 4 then e.remark when 16 then ass.remark ELSE null END ) remark, list.serial_number AS cargoSerialNumber, list.license_plate, list.actual_user_name, list.audit_user_name, supplier.name AS supplierName, mbw.name AS workshopNames, link.weight AS mete, (case link.product_type when 8 then sp.bool_return else 0 end) bool_return, link.* FROM mes_building_cargo_list list INNER JOIN mes_building_cargo_list_product_link AS link ON list.id = link.cargo_list_id and link.warehouse_type in(0,2) LEFT JOIN mes_building_supplier_price AS mbsp ON mbsp.id = list.supplier_price_id and mbsp.bool_delete_enum = 0 LEFT JOIN scm_supplier supplier on supplier.id = mbsp.supplier_id and supplier.bool_delete_enum = 0 LEFT JOIN tech_artifact a ON link.product_type = 2 AND link.product_id = a.id AND a.bool_delete_enum = 0 LEFT JOIN tech_enclosure e ON link.product_type = 4 AND link.product_id = e.id AND e.bool_delete_enum = 0 LEFT JOIN tech_standard_part sp ON link.product_type = 8 AND link.product_id = sp.id AND sp.bool_delete_enum = 0 LEFT JOIN tech_machine_part mp ON link.product_type = 1 AND link.product_id = mp.id AND mp.bool_delete_enum = 0 LEFT JOIN tech_assemble ass ON link.product_type = 16 AND link.product_id = ass.id AND ass.bool_delete_enum = 0 LEFT JOIN mes_building_warehouse_summary summary on summary.id = link.warehouse_record_id and summary.bool_delete_enum = 0 LEFT JOIN mes_building_workshop mbw ON summary.workshop_id= mbw.id AND mbw.bool_delete_enum=0 WHERE list.bool_delete_enum = 0 AND link.bool_delete_enum = 0 AND list.`status` IN ( 4, 8 ) AND list.delivery_status = 1 AND (link.product_type IN ( 4, 8 ) or (link.product_type = 1 and mp.bool_send_directly = 1) or (link.product_type = 2 and a.bool_all_part_send_directly = 0) or (link.product_type = 16 and ass.bool_send_directly = 1))
AND list.project_id IN
#{projectId}
AND link.product_type = #{productType}
and date(list.audit_time) >= date(#{auditStartDate})
and date(list.audit_time) <= date(#{auditEndDate})
) temp
AND temp.monomer_id = #{monomerId}
AND temp.name like concat('%',#{name},'%')
AND temp.serial_number like concat('%',#{serialNumber},'%')
order by temp.audit_time desc, temp.id desc
